import sys

def main():
    input_data = sys.stdin.read().split()
    if not input_data:
        return
    n = int(input_data[0])
    k = int(input_data[1])

    max_tot = n * (n - 1) // 2
    if max_tot <= k:
        print("no solution")
        return

    points = []
    x = 0
    y = 0
    step_x = 1
    step_y = 1000000000 // n + 1

    for i in range(n):
        points.append((x, y))
        if i % 2 == 0:
            x += step_x
        else:
            y += step_y

    points.sort(key=lambda p: (p[0], p[1]))

    d = float('inf')
    tot = 0
    for i in range(n):
        for j in range(i + 1, n):
            tot += 1
            if points[j][0] - points[i][0] >= d:
                break
            dist_sq = (points[i][0] - points[j][0])**2 + (points[i][1] - points[j][1])**2
            dist = dist_sq ** 0.5
            if dist < d:
                d = dist

    if tot > k:
        for px, py in points:
            print(px, py)
    else:
        points = [(i, i * 1000000000 // n) for i in range(n)]
        points.sort(key=lambda p: (p[0], p[1]))

        d = float('inf')
        tot = 0
        for i in range(n):
            for j in range(i + 1, n):
                tot += 1
                if points[j][0] - points[i][0] >= d: break
                dist_sq = (points[i][0] - points[j][0])** 2 + (points[i][1] - points[j][1])** 2
                dist = dist_sq ** 0.5
                if dist < d: d = dist

        if tot > k:
            for px, py in points:
                print(px, py)
        else:
            points = [(i, 0) for i in range(n)]
            points.sort(key=lambda p: (p[0], p[1]))            
            for px, py in points:
                print(px, py)

if __name__ == "__main__":
    main()
